430	<script>
431	(function () {
432	  // The minimal animation stylesheet each asset depends on. Embedded inside the
433	  // copied <svg> so the asset stays self-animating when dropped into any project.
434	  var ANIM_CSS = [
435	    '@keyframes float{0%,100%{transform:translateY(0)}50%{transform:translateY(-7px)}}',
436	    '@keyframes blink{0%,92%,100%{transform:scaleY(1)}96%{transform:scaleY(.1)}}',
437	    '@keyframes sway{0%,100%{transform:rotate(-4deg)}50%{transform:rotate(4deg)}}',
438	    '@keyframes pop{0%{transform:scale(0);opacity:0}60%{transform:scale(1.15);opacity:1}100%{transform:scale(1)}}',
439	    '@keyframes draw{to{stroke-dashoffset:0}}',
440	    '@keyframes confetti{0%{transform:translateY(0) rotate(0);opacity:1}100%{transform:translateY(-46px) rotate(220deg);opacity:0}}',
441	    '@keyframes spin{to{transform:rotate(360deg)}}',
442	    '@keyframes pulse{0%,100%{transform:scale(1);opacity:.9}50%{transform:scale(1.12);opacity:.5}}',
443	    '@keyframes wiggle{0%,100%{transform:rotate(0)}25%{transform:rotate(8deg)}75%{transform:rotate(-8deg)}}',
444	    '@keyframes orbit{to{transform:rotate(-360deg)}}',
445	    '@keyframes rise{0%,100%{transform:translateY(0)}50%{transform:translateY(-4px)}}',
446	    '@keyframes twinkle{0%,100%{opacity:.2;transform:scale(.6)}50%{opacity:1;transform:scale(1)}}',
447	    '@keyframes heartbeat{0%,100%{transform:scale(1)}15%{transform:scale(1.13)}30%{transform:scale(1)}45%{transform:scale(1.08)}}',
448	    '.a-float{animation:float 4s ease-in-out infinite;transform-origin:center}',
449	    '.a-blink{animation:blink 5s ease-in-out infinite;transform-origin:center}',
450	    '.a-sway{animation:sway 4.5s ease-in-out infinite;transform-origin:50% 90%}',
451	    '.a-pop{animation:pop .7s cubic-bezier(.2,1.3,.4,1) both}',
452	    '.a-spin{animation:spin 1.4s linear infinite;transform-origin:center}',
453	    '.a-pulse{animation:pulse 2.6s ease-in-out infinite;transform-origin:center}',
454	    '.a-wiggle{animation:wiggle 3.5s ease-in-out infinite;transform-origin:50% 80%}',
455	    '.a-orbit{animation:orbit 6s linear infinite;transform-origin:center}',
456	    '.a-rise{animation:rise 3s ease-in-out infinite;transform-origin:center}',
457	    '.a-twinkle{animation:twinkle 2s ease-in-out infinite;transform-origin:center}',
458	    '.a-heartbeat{animation:heartbeat 2.4s ease-in-out infinite;transform-origin:center}',
459	    '.draw{stroke-dasharray:90;stroke-dashoffset:90;animation:draw 1s ease-out .25s forwards}',
460	    '.conf{animation:confetti 1.3s ease-out infinite}',
461	    '.conf:nth-child(odd){animation-duration:1.6s}',
462	    '@media (prefers-reduced-motion:reduce){.a-float,.a-blink,.a-sway,.a-pop,.a-spin,.a-pulse,.a-wiggle,.a-orbit,.a-rise,.a-twinkle,.a-heartbeat,.conf{animation:none}.draw{stroke-dashoffset:0}}'
463	  ].join('');
464	
465	  // Build standalone, self-animating SVG markup for one card's stage <svg>.
466	  function buildSvg(svg) {
467	    var clone = svg.cloneNode(true);
468	    var style = document.createElementNS('http://www.w3.org/2000/svg', 'style');
469	    style.textContent = ANIM_CSS;
470	    clone.insertBefore(style, clone.firstChild);
471	    if (!clone.getAttribute('xmlns')) clone.setAttribute('xmlns', 'http://www.w3.org/2000/svg');
472	    return clone.outerHTML.replace(/></g, '>\n<');
473	  }
474	
475	  var toast = document.getElementById('toast'), toastTimer;
476	  function showToast(msg) {
477	    toast.textContent = msg;
478	    toast.classList.add('show');
479	    clearTimeout(toastTimer);
480	    toastTimer = setTimeout(function () { toast.classList.remove('show'); }, 1800);
481	  }
482	
483	  var COPY_IC = '<svg class="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="9" y="9" width="11" height="11" rx="2"/><path d="M5 15V5a2 2 0 0 1 2-2h10"/></svg>';
484	  var DONE_IC = '<svg class="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M5 13l4 4L19 7"/></svg>';
485	  var DL_IC   = '<svg class="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3v12"/><path d="M7 11l5 5 5-5"/><path d="M5 20h14"/></svg>';
486	
487	  // "Nothing here — yet" -> "nothing-here-yet" for a friendly .svg filename
488	  function slugify(name) {
489	    return (name || 'asset').toLowerCase()
490	      .replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '') || 'asset';
491	  }
492	
493	  // Save a standalone .svg document (self-animating markup + XML prolog) to disk.
494	  function downloadSvg(markup, filename) {
495	    var doc = '<?xml version="1.0" encoding="UTF-8"?>\n' + markup;
496	    var blob = new Blob([doc], { type: 'image/svg+xml' });
497	    var url = URL.createObjectURL(blob);
498	    var a = document.createElement('a');
499	    a.href = url; a.download = filename;
500	    document.body.appendChild(a); a.click(); document.body.removeChild(a);
501	    setTimeout(function () { URL.revokeObjectURL(url); }, 1000);
502	  }
503	
504	  function fallbackCopy(text) {
505	    var ta = document.createElement('textarea');
506	    ta.value = text; ta.style.position = 'fixed'; ta.style.opacity = '0';
507	    document.body.appendChild(ta); ta.select();
508	    var ok = false; try { ok = document.execCommand('copy'); } catch (e) {}
509	    document.body.removeChild(ta); return ok;
510	  }
511	
512	  document.querySelectorAll('.card').forEach(function (card) {
513	    var svg = card.querySelector('.stage svg');
514	    if (!svg) return;
515	    var name = (card.querySelector('.name') || {}).textContent || 'asset';
516	    var btn = document.createElement('button');
517	    btn.type = 'button';
518	    btn.className = 'copy-btn';
519	    btn.innerHTML = COPY_IC + '<span>Copy SVG</span>';
520	    btn.setAttribute('aria-label', 'Copy SVG markup for ' + name);
521	
522	    btn.addEventListener('click', function () {
523	      var markup = buildSvg(svg);
524	      var done = function () {
525	        btn.classList.add('done');
526	        btn.innerHTML = DONE_IC + '<span>Copied!</span>';
527	        showToast('SVG copied — paste it anywhere');
528	        setTimeout(function () {
529	          btn.classList.remove('done');
530	          btn.innerHTML = COPY_IC + '<span>Copy SVG</span>';
531	        }, 1800);
532	      };
533	      if (navigator.clipboard && navigator.clipboard.writeText) {
534	        navigator.clipboard.writeText(markup).then(done, function () {
535	          if (fallbackCopy(markup)) done(); else showToast('Copy failed — select manually');
536	        });
537	      } else {
538	        if (fallbackCopy(markup)) done(); else showToast('Copy failed — select manually');
539	      }
540	    });
541	
542	    var dl = document.createElement('button');
543	    dl.type = 'button';
544	    dl.className = 'dl-btn';
545	    dl.innerHTML = DL_IC;
546	    dl.setAttribute('aria-label', 'Download ' + name + ' as an SVG file');
547	    dl.title = 'Download .svg';
548	    dl.addEventListener('click', function () {
549	      downloadSvg(buildSvg(svg), slugify(name) + '.svg');
550	      showToast('Downloaded ' + slugify(name) + '.svg');
551	    });
552	
553	    var actions = document.createElement('div');
554	    actions.className = 'actions';
555	    actions.appendChild(btn);
556	    actions.appendChild(dl);
557	    card.querySelector('.body').appendChild(actions);
558	  });
559	
560	  // ---- Journey-stage filtering ----
561	  var cards = Array.prototype.slice.call(document.querySelectorAll('.card'));
562	  var chips = Array.prototype.slice.call(document.querySelectorAll('.filterbar .chip'));
563	  var countEl = document.getElementById('fbCount');
564	  var emptyNote = document.getElementById('emptyNote');
565	
566	  function applyFilter(filter) {
567	    var shown = 0;
568	    cards.forEach(function (card) {
569	      var match = filter === 'all' || card.getAttribute('data-cat') === filter;
570	      card.classList.toggle('hide', !match);
571	      if (match) shown++;
572	    });
573	    chips.forEach(function (chip) {
574	      chip.setAttribute('aria-pressed', String(chip.getAttribute('data-filter') === filter));
575	    });
576	    countEl.textContent = shown + (shown === 1 ? ' asset' : ' assets');
577	    emptyNote.style.display = shown === 0 ? 'block' : 'none';
578	  }
579	
580	  chips.forEach(function (chip) {
581	    chip.addEventListener('click', function () { applyFilter(chip.getAttribute('data-filter')); });
582	  });
583	
584	  // ---- Global motion toggle (freeze/resume all asset animations) ----
585	  var motionBtn = document.getElementById('motionToggle');
586	  if (motionBtn) {
587	    motionBtn.addEventListener('click', function () {
588	      var paused = document.body.classList.toggle('motion-paused');
589	      motionBtn.setAttribute('aria-pressed', String(paused));
590	      motionBtn.setAttribute('aria-label', paused ? 'Resume all asset animations' : 'Pause all asset animations');
591	    });
592	  }
593	})();
